func (w *Writer) Write(bs []byte) (n int, err error) {


	if !w.Log.Core().Enabled(w.Level) {
		return len(bs), nil
	}

	n = len(bs)
	for len(bs) > 0 {
		bs = w.writeLine(bs)
	}

	return n, nil
}

func (w *Writer) writeLine(line []byte) (remaining []byte) {

	idx := bytes.IndexByte(line, '\n')
	if idx < 0 {

		w.buff.Write(line)
		return nil
	}


	line, remaining = line[:idx], line[idx+1:]



	if w.buff.Len() == 0 {
		w.log(line)
		return
	}

	w.buff.Write(line)



	w.flush(true )

	return remaining
}

func (w *Writer) Close() error {

	return w.Sync()
}

func (w *Writer) Sync() error {




	w.flush(false )
	return nil
}

func (w *Writer) flush(allowEmpty bool) {

	if allowEmpty || w.buff.Len() > 0 {
		w.log(w.buff.Bytes())
	}
	w.buff.Reset()
}

func (w *Writer) log(b []byte) {

	if ce := w.Log.Check(w.Level, string(b)); ce != nil {
		ce.Write()
	}
}

